t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
import re
def parse(label):
    m=re.search(label+r' \((\d+)x(\d+)\):\n',t)
    h,w=int(m[1]),int(m[2])
    return [[int(x) for x in r.split()] for r in t[m.end():].split('\n')[:h]]
D1={'in':parse('Demo pair 1 input'),'out':parse('Demo pair 1 output')}
