T=parse('Test input')
from collections import Counter
def transform(g):
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg or seen[i][j]: continue
            c=g[i][j]; comp=[]; st=[(i,j)]; seen[i][j]=True
            while st:
                y,x=st.pop(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; st.append((ny,nx))
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            # ring check: comp == border of bbox
            border={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if y in(y0,y1) or x in(x0,x1)}
            if set(comp)!=border or y1-y0<2 or x1-x0<2: continue
            area=(y1-y0-1)*(x1-x0-1)
            fill=7 if area%2==1 else 2
            for y in range(y0+1,y1):
                for x in range(x0+1,x1):
                    if g[y][x]==bg: out[y][x]=fill
    return out
for n,D in (('1',D1),('2',D2)):
    print(n, transform(D['in'])==D['out'])
print([[v for v in r] for r in transform(T)])

