def is_ring(comp):
    """True if the component exactly covers the border of its bounding box (at least 3x3)."""
    ys = [p[0] for p in comp]; xs = [p[1] for p in comp]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    if y1 - y0 < 2 or x1 - x0 < 2:
        return False
    border = {(y, x) for y in range(y0, y1 + 1) for x in range(x0, x1 + 1)
              if y in (y0, y1) or x in (x0, x1)}
    return set(comp) == border

def fill_rings(grid, fill_of):
    """Fill the interior of every rectangular ring with fill_of(interior_area); interiors keep non-background cells."""
    bg = background(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for color in {v for row in grid for v in row} - {bg}:
